/**
 * Own item art: `item id` -> URL of an imported SVG.
 *
 * Contract: SVGs here carry no fixed colour (they are used as a CSS mask and take the group's
 * colour through `currentColor`). They are generated by Claude Code and approved by the owner,
 * as with the Grimoire art. Add one like this:
 *
 *   import spellbook from './spellbook.svg';
 *   export const ITEM_ART = { spellbook: spellbook.src };
 *
 * (`.svg` imports are typed by next/image-types, see static-assets.d.ts; use `.src`.)
 */
export const ITEM_ART: Readonly<Record<string, string>> = {};
